-- msgplane's Quotes > Archived holds 6,582 records. Ours held 118.
--
-- The importer's status list has no 'cancelled' entry, so every cancelled
-- quote fell through to 'hold': Quotes > Hold showed 6,452 where the old
-- system shows 33, and Quotes > Archived showed 118 where it shows 6,582. The
-- two tabs were effectively swapped. Separately 'on-hold-quote' substring
-- matched 'quote', so the 33 genuinely held quotes were filed as live quotes
-- and their hold state was lost.
--
-- Neither fact survives anywhere in the database -- msgplane_status is null on
-- all of these rows -- so the source of truth is the export in
-- C:/Users/User/Downloads/msgplane-*.json, and the load_numbers are listed
-- here verbatim rather than re-derived, so this migration replays identically
-- with or without those files.
--
-- pipeline_stage is deliberately NOT set here: trg_loads_pipeline_stage (0030)
-- reads it off the status being parked FROM, so these keep stage 'quote'.
--
-- Counts at the time of writing: 6571 rows to 'cancelled', 33 to 'hold'.

-- Audit trail first, so the previous status is recoverable per row.
insert into load_status_history (load_id, status, changed_by, note)
select l.id, 'cancelled', null,
       'Import correction: msgplane says cancelled, was ' || l.status
  from loads l
